import * as THREE from './three.module.js';
import {racketWoodMaterials} from './racket-wood.js';
import {strokePose,armTo} from './arm-pose.js';
export function createArmRig(skin,cloth,wood,bandMaterial=null){const racketWood=racketWoodMaterials(),root=new THREE.Group(),bones=[],up=new THREE.Vector3(0,1,0);
 function segment(radius,material){const m=new THREE.Mesh(new THREE.CapsuleGeometry(radius,1-2*radius,6,24),material);m.castShadow=true;root.add(m);return m;}
 const upper=segment(.061,skin),forearm=segment(.050,skin),sleeve=segment(.084,cloth);const elbow=new THREE.Mesh(new THREE.SphereGeometry(.054,24,16),skin),wrist=new THREE.Mesh(new THREE.SphereGeometry(.046,24,16),skin);root.add(elbow,wrist);
 const sweatband=bandMaterial?segment(.055,bandMaterial):null;if(sweatband)sweatband.userData.wristband=true;
 const racket=new THREE.Group();root.add(racket);const grip=new THREE.Mesh(new THREE.CylinderGeometry(.026,.026,.25,10),new THREE.MeshStandardMaterial({color:'#34312b',roughness:1}));grip.rotation.z=Math.PI/2;grip.position.x=-.125;racket.add(grip);const shaft=new THREE.Mesh(new THREE.CylinderGeometry(.021,.022,.16,10),racketWood.shaft);shaft.rotation.z=Math.PI/2;shaft.position.x=-.29;racket.add(shaft);const rim=new THREE.Mesh(new THREE.TorusGeometry(.18,.019,8,40),racketWood.rim);rim.position.x=-.45;rim.scale.set(1.22,.88,1);racket.add(rim);
 const strings=[];for(let y=-.12;y<=.12;y+=.04){const dx=.205*Math.sqrt(Math.max(0,1-y*y/(.15*.15)));strings.push(-.45-dx,y,0,-.45+dx,y,0);}for(let x=-.63;x<-.25;x+=.045){const dy=.145*Math.sqrt(Math.max(0,1-(x+.45)**2/(.215*.215)));strings.push(x,-dy,0,x,dy,0);}const sg=new THREE.BufferGeometry();sg.setAttribute('position',new THREE.Float32BufferAttribute(strings,3));racket.add(new THREE.LineSegments(sg,new THREE.LineBasicMaterial({color:'#ece5cf'})));
 function fit(mesh,a,b){const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),d=B.clone().sub(A);mesh.position.copy(A).add(B).multiplyScalar(.5);mesh.scale.y=d.length();mesh.quaternion.setFromUnitVectors(up,d.normalize());}
 function pose(position,hand,kind='regular',ready=0){let p=strokePose(position,hand);const blend=Math.max(0,Math.min(1,ready)),quaternion=new THREE.Quaternion().setFromEuler(new THREE.Euler(kind==='lob'?.65:0,p.yaw,0));if(blend>0){const desired=p.wrist.map((v,i)=>v+([-.035,.89,.38][i]-v)*blend);const pole=p.elbow.map((v,i)=>(v-p.shoulder[i])*(1-blend)+[-.6,-.2,0][i]*blend);p={...p,...armTo(p.shoulder,desired,pole)};const readyRotation=new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(-1,0,0),new THREE.Vector3(.035,.43,.08).normalize());readyRotation.multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(-1,0,0),Math.PI/2));quaternion.slerp(readyRotation,blend);p.shaft=new THREE.Vector3(-1,0,0).applyQuaternion(quaternion).toArray();p.head=p.wrist.map((v,i)=>v+p.shaft[i]*.45);}fit(upper,p.shoulder,p.elbow);fit(forearm,p.elbow,p.wrist);const cuff=p.shoulder.map((v,i)=>v+(p.elbow[i]-v)*.52);fit(sleeve,p.shoulder,cuff);elbow.position.set(...p.elbow);wrist.position.set(...p.wrist);if(sweatband)fit(sweatband,p.elbow.map((v,i)=>v+(p.wrist[i]-v)*.78),p.elbow.map((v,i)=>v+(p.wrist[i]-v)*.96));racket.position.set(...p.wrist);racket.quaternion.copy(quaternion);racket.scale.x=1;return p;}
 function poseService(p,shaft){fit(upper,p.shoulder,p.elbow);fit(forearm,p.elbow,p.wrist);fit(sleeve,p.shoulder,p.shoulder.map((v,i)=>v+(p.elbow[i]-v)*.52));elbow.position.set(...p.elbow);wrist.position.set(...p.wrist);if(sweatband)fit(sweatband,p.elbow.map((v,i)=>v+(p.wrist[i]-v)*.78),p.elbow.map((v,i)=>v+(p.wrist[i]-v)*.96));racket.position.set(...p.wrist);racket.quaternion.setFromUnitVectors(new THREE.Vector3(-1,0,0),new THREE.Vector3(...shaft));return {head:p.wrist.map((v,i)=>v+shaft[i]*.45)};}
 pose(0,1);return {root,pose,poseService};}
